using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Web.Script.Serialization;
class AddTavernDemoGroups{static void Main(){string file="D:/WORK/Cet6Story/assets/tavern/listening/groups.json";var json=new JavaScriptSerializer();var bank=json.Deserialize<List<TavernListeningGroup>>(File.ReadAllText(file));foreach(int level in new[]{4,6}){for(int n=0;n<2;n++){string text=n==0?"A college will open a new study room next Tuesday. The room is on the second floor of the library. It has thirty seats. Students can use it from seven in the morning until nine in the evening. Booking is free, but students must bring their student cards. Question one: When will the new room open? Question two: Where is it located? Question three: How many seats does it have? Question four: What must students bring?":"A farmer has started delivering fresh vegetables to local restaurants. Deliveries take place every Friday morning. Customers order through a website before Wednesday evening. The farmer uses reusable boxes to reduce waste. Empty boxes are collected on the next delivery. Question one: Who are the customers? Question two: When are orders delivered? Question three: How do customers place orders? Question four: Why does the farmer use reusable boxes?";string[][] opts=n==0?new[]{new[]{"Next Tuesday.","Next Friday.","Next Monday.","Tomorrow morning."},new[]{"In the dining hall.","On the library's second floor.","At the station.","In the sports centre."},new[]{"Ten.","Twenty.","Thirty.","Forty."},new[]{"Their passports.","Their own chairs.","A lunch box.","Their student cards."}}:new[]{new[]{"Local restaurants.","Foreign universities.","Airport passengers.","Museum visitors."},new[]{"Monday afternoon.","Friday morning.","Wednesday evening.","Sunday night."},new[]{"By sending letters.","By visiting the farm.","Through a website.","Through a newspaper."},new[]{"To advertise the farm.","To keep vegetables frozen.","To increase delivery time.","To reduce waste."}};var q=new List<TavernListeningQuestion>();for(int i=0;i<4;i++)q.Add(new TavernListeningQuestion{options=opts[i],answer=i,explanation="根据材料选择："+opts[i][i]});bank.Add(new TavernListeningGroup{id="demo-cet"+level+"-extra-"+n,level=level,title=(level==4?"四级":"六级")+"模拟 · "+(n==0?"校园自习室":"农场配送"),source="原创模拟材料 · 非历年真题",audio="demo-cet"+level+"-extra-"+n+".wav",transcript=text,questions=q});}}File.WriteAllText(file,json.Serialize(bank));}}
